import Foundation
import Supabase


extension Notification.Name {

    static let foodLogDidChange =
        Notification.Name("FoodLogDidChange")
}


struct FoodSaveOutcome {
    let reward: FoodLoggingRewardResponse?
}

nonisolated struct FoodLoggingRewardResponse: Decodable {
    let awarded: Bool
    let reward_date: String
    let total_xp: Int64
    let crafting_fragments: Int64
}

private nonisolated struct InsertedFoodLog: Decodable {
    let id: UUID
}

struct FoodLogService {

    // MARK: - Save Food Log

    func saveFoodLog(_ foodLog: NewFoodLog) async throws -> FoodSaveOutcome {

        // Save the food and retrieve its generated ID
        let saved: InsertedFoodLog = try await supabase
            .from("food_logs")
            .insert(foodLog)
            .select("id")
            .single()
            .execute()
            .value
        
        
        // Store any achievements unlocked by this food entry
        var unlockedAchievements: AchievementClaimResponse?

        // Notify the Dashboard when reward processing finishes
        defer {

            NotificationCenter.default.post(
                name: .foodLogDidChange,
                object: unlockedAchievements
            )
        }


        do {

            // Ask Supabase to check the food logging reward
            let rewards: [FoodLoggingRewardResponse] = try await supabase
                .rpc(
                    "claim_food_logging",
                    params: [
                        "p_food_log_id": saved.id.uuidString
                    ]
                )
                .execute()
                .value

            let reward = rewards.first

            
            // MARK: - Automatic Food Logging Achievements

            if reward?.awarded == true {

                do {

                    // Claim any achievements earned through food logging
                    let result = try await GamificationService()
                        .claimAchievements()

                    // Remember newly unlocked achievements
                    // so the Dashboard can display them
                    if result.newly_unlocked > 0 {

                        unlockedAchievements = result
                    }

                } catch {

                    // Food and its daily reward have already saved
                    print(
                        "Food reward succeeded, but achievement check failed: \(error.localizedDescription)"
                    )
                }
            }


            // Return the original food reward result
            return FoodSaveOutcome(reward: reward)

        } catch {

            // The food was saved even if checking rewards failed
            print(
                "Food saved, but reward check failed: \(error.localizedDescription)"
            )

            return FoodSaveOutcome(reward: nil)
        }
    }

    // MARK: - Fetch Food Logs

    // Fetch the current user's food logs
    func fetchFoodLogs() async throws -> [FoodLog] {

        guard let currentUserID = supabase.auth.currentUser?.id else {
            return []
        }

        let foodLogs: [FoodLog] = try await supabase
            .from("food_logs")
            .select()
            .eq("user_id", value: currentUserID.uuidString)
            .order("consumed_at", ascending: false)
            .execute()
            .value

        return foodLogs
    }

    // MARK: - Fetch Today's Food Logs

    func fetchTodayFoodLogs() async throws -> [FoodLog] {

        // Make sure a user is logged in
        guard let currentUserID =
                supabase.auth.currentUser?.id else {

            return []
        }

        // Get the beginning of today
        let startOfToday =
            Calendar.current.startOfDay(
                for: Date()
            )

        // Get the beginning of tomorrow
        guard let startOfTomorrow =
                Calendar.current.date(
                    byAdding: .day,
                    value: 1,
                    to: startOfToday
                ) else {

            return []
        }

        // Convert the Dates into timestamps
        // Supabase/PostgreSQL can compare
        let formatter = ISO8601DateFormatter()

        let startTimestamp =
            formatter.string(
                from: startOfToday
            )

        let endTimestamp =
            formatter.string(
                from: startOfTomorrow
            )

        // Get only this user's food logs
        // that were created today
        let foodLogs: [FoodLog] = try await supabase
            .from("food_logs")
            .select()
            .eq(
                "user_id",
                value: currentUserID.uuidString
            )
            .gte(
                "consumed_at",
                value: startTimestamp
            )
            .lt(
                "consumed_at",
                value: endTimestamp
            )
            .order(
                "consumed_at",
                ascending: false
            )
            .execute()
            .value

        return foodLogs
    }

    // MARK: - Delete Food Log

    // Delete one food log
    func deleteFoodLog(id: UUID) async throws {

        try await supabase
            .from("food_logs")
            .delete()
            .eq("id", value: id.uuidString)
            .execute()
    }
}
